---@class PageChatQuick
PageChatQuick = class("PageChatQuick")

function PageChatQuick:initialize()
end

function PageChatQuick:InitData(parentPref,sendCallBack)
    self.parentPref = parentPref
    self.uiModuleID = UIModuleID.ChatView
    self.sendCallBack=sendCallBack
    self.Page_QuickChat = UIUtil.GetChild("Page_QuickChat",self.parentPref)
    self.ShortChatListScrollView = UIUtil.GetTypeChildWightByParent("ShortChatList", self.parentPref, typeof(MoreRowScrollView))
    self.ShortMsg = {}
    local cfg = CommonHelper:GetTableDataByID(ConfigNames.dictcalc_config, CommonCfgKey.UnlimitedChatLevel)
    local tip = CommonHelper:GetTempStr_Default(TemplateStringID.QuickChatTip,cfg.varval)
    CommonHelper:SetText("inputcontent", self.parentPref, tip)
    CommonHelper:HButtonSetCallback("CloseQuickChat", self.Page_QuickChat, function()
        self:CloseSelf()
    end)
    CommonHelper:HButtonSetCallback("quickspeakbtn", self.parentPref, function(param)
        local chatIntervalTime = ChatDataManager:Get():GetTimerIdOrTimeByChatType(ChatType.World, ChatTimeOrId.Time)
        local unixNowTime = CommonHelper:ConvertDateTimeToInt(CommonHelper:GetNowTime())
        local chatLeftTime = chatIntervalTime - unixNowTime
        if chatLeftTime < 0 then
            self:Open()
        end
    end)
    self:InitShortMsg()
end

function PageChatQuick:Open()
    self.Page_QuickChat:SetActive(true)
    self:InitShortList()
end

function PageChatQuick:InitShortMsg()
    ---@type quickspeak_config
    local quickspeak_config = ClientDataManager:Get():GetDataTable(ConfigNames.quickspeak_config)
    quickspeak_config = quickspeak_config.GetConfigData()
    for id, msg in pairs(quickspeak_config) do
        if msg.type == ChatQuickType.World then
            table.insert(self.ShortMsg, CommonHelper:GetTempStr_Default(msg.content))
        end
    end
end


function PageChatQuick:InitShortList()
    local UpdateFunc = function(dataIndex, itemObj, scroll)
        local msgData =self.ShortMsg[dataIndex + 1]
        local content =CommonHelper:GetTempStr_Default(msgData)
        CommonHelper:SetText("###Text", itemObj, content)
        CommonHelper:HButtonSetCallback("ViewDetailBtn", itemObj, function(param)
            if self.sendCallBack then
                self.sendCallBack()
            end
            ChatSubsystem:Get():SendMsg_ChatData(ChatType.World, content,0,nil,nil,nil,nil,1)
            self:CloseSelf()
        end)
    end
    CommonHelper:InitMoreRowScrollView(self.ShortChatListScrollView, #self.ShortMsg, 1, UpdateFunc, true)
end


function PageChatQuick:CloseSelf()
    self.Page_QuickChat:SetActive(false)
end